// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address caller) internal {
        vm.assume(true);
        bool reverted;
        address owner;
        try c.owner() returns (address __r) { owner = __r; } catch { return; }
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        assertTrue((address(this) == owner) == (!reverted));
    }

    function testFuzz_run(address caller) public {
        _run(caller);
    }

    receive() external payable {}
}
